INSERT INTO `blog_posts` (`id`, `workspaceId`, `slug`, `title`, `excerpt`, `content`, `featuredImage`, `categoryId`, `authorId`, `authorName`, `seoTitle`, `metaDescription`, `tags`, `status`, `publishedAt`, `isDemo`, `createdAt`, `updatedAt`) VALUES
('cmuojn06p01jzzs7dh2mb0gsy', 'cmuojlaux0000uz7de9mahyza', 'how-to-brief-a-video-editor-so-you-get-it-right-the-first-time', 'How to brief a video editor so you get it right the first time', 'A great brief removes 80% of revision rounds. Here\'s the exact structure we use with clients.', '## How to brief a video editor so you get it right the first time\n\nA great brief removes 80% of revision rounds. Here\'s the exact structure we use with clients.\n\nThis is **sample content** included with the demo data so the blog is not empty. Replace it from **Admin → Content → Blog**, or remove all demo data with `npm run db:clear-demo`.\n\n### Key points\n\n- Start from the outcome, not the tool.\n- Decide what \"done\" looks like before the first draft.\n- Give timestamped feedback — it\'s faster for everyone.\n', '/assets/demo/work-1.jpg', 'cmuojn06n01jyzs7dmbkfsd57', NULL, 'Ayesha Khan', NULL, NULL, '[\"editing\",\"workflow\"]', 'PUBLISHED', '2026-09-27 20:14:14.448', '1', '2026-09-30 20:14:14.449', '2026-09-30 20:14:14.449'),
('cmuojn06s01k0zs7d9i3d4qqg', 'cmuojlaux0000uz7de9mahyza', 'short-form-vs-long-form-where-should-your-budget-go', 'Short-form vs long-form: where should your budget go?', 'A practical way to decide between Reels and YouTube for your next quarter.', '## Short-form vs long-form: where should your budget go?\n\nA practical way to decide between Reels and YouTube for your next quarter.\n\nThis is **sample content** included with the demo data so the blog is not empty. Replace it from **Admin → Content → Blog**, or remove all demo data with `npm run db:clear-demo`.\n\n### Key points\n\n- Start from the outcome, not the tool.\n- Decide what \"done\" looks like before the first draft.\n- Give timestamped feedback — it\'s faster for everyone.\n', '/assets/demo/work-2.jpg', 'cmuojn06n01jyzs7dmbkfsd57', NULL, 'Ayesha Khan', NULL, NULL, '[\"editing\",\"workflow\"]', 'PUBLISHED', '2026-09-18 20:14:14.452', '1', '2026-09-30 20:14:14.452', '2026-09-30 20:14:14.452'),
('cmuojn06t01k1zs7dwe6neld1', 'cmuojlaux0000uz7de9mahyza', 'the-anatomy-of-a-great-podcast-trailer', 'The anatomy of a great podcast trailer', 'Hooks, pacing, sound design and the three shots every trailer needs.', '## The anatomy of a great podcast trailer\n\nHooks, pacing, sound design and the three shots every trailer needs.\n\nThis is **sample content** included with the demo data so the blog is not empty. Replace it from **Admin → Content → Blog**, or remove all demo data with `npm run db:clear-demo`.\n\n### Key points\n\n- Start from the outcome, not the tool.\n- Decide what \"done\" looks like before the first draft.\n- Give timestamped feedback — it\'s faster for everyone.\n', '/assets/demo/work-3.jpg', 'cmuojn06n01jyzs7dmbkfsd57', NULL, 'Ayesha Khan', NULL, NULL, '[\"editing\",\"workflow\"]', 'PUBLISHED', '2026-09-09 20:14:14.453', '1', '2026-09-30 20:14:14.453', '2026-09-30 20:14:14.453'),
('cmuojn06v01k2zs7dfrk5ghaa', 'cmuojlaux0000uz7de9mahyza', 'revision-rounds-explained-what-counts-and-what-doesn-t', 'Revision rounds explained: what counts and what doesn\'t', 'How to give feedback that gets results without burning through your revision allowance.', '## Revision rounds explained: what counts and what doesn\'t\n\nHow to give feedback that gets results without burning through your revision allowance.\n\nThis is **sample content** included with the demo data so the blog is not empty. Replace it from **Admin → Content → Blog**, or remove all demo data with `npm run db:clear-demo`.\n\n### Key points\n\n- Start from the outcome, not the tool.\n- Decide what \"done\" looks like before the first draft.\n- Give timestamped feedback — it\'s faster for everyone.\n', '/assets/demo/work-4.jpg', 'cmuojn06n01jyzs7dmbkfsd57', NULL, 'Ayesha Khan', NULL, NULL, '[\"editing\",\"workflow\"]', 'PUBLISHED', '2026-08-31 20:14:14.455', '1', '2026-09-30 20:14:14.455', '2026-09-30 20:14:14.455');
INSERT INTO `case_studies` (`id`, `workspaceId`, `portfolioProjectId`, `slug`, `title`, `clientName`, `industry`, `summary`, `problem`, `objective`, `strategy`, `creativeDirection`, `beforeVideoUrl`, `afterVideoUrl`, `heroImage`, `results`, `clientFeedback`, `feedbackAuthor`, `deliverables`, `timeline`, `seoTitle`, `seoDescription`, `status`, `isDemo`, `createdAt`, `updatedAt`) VALUES
('cmuojn06901jtzs7dnwiqm8jt', 'cmuojlaux0000uz7de9mahyza', 'cmuojn05k01jjzs7dshk7srpl', 'how-northwind-cut-listing-video-turnaround-from-2-weeks-to-3', 'How Northwind cut listing video turnaround from 2 weeks to 3 days', 'Northwind Realty Group', 'Real estate', 'A regional brokerage needed consistent, premium listing films without hiring in-house.', 'Video production was slow and inconsistent, with feedback scattered across email and chat.', 'A repeatable pipeline: brief → draft → feedback → approval, with predictable turnaround.', 'A dedicated editor, a structured brief and timestamped review on every draft.', 'Clean, cinematic, on-brand motion with tasteful sound design.', NULL, NULL, '/assets/demo/work-1.jpg', '{\"Turnaround\":\"3 days\",\"Videos / month\":\"12\",\"Revision rounds\":\"1.4 avg\"}', 'The process is what makes it — I always know where my project is.', 'Northwind Realty Group', '[\"Master edit\",\"Social cut-downs\",\"Captions\"]', '3 weeks', NULL, NULL, 'PUBLISHED', '1', '2026-09-30 20:14:14.433', '2026-09-30 20:14:14.433'),
('cmuojn06c01juzs7dzd06kte8', 'cmuojlaux0000uz7de9mahyza', 'cmuojn05n01jkzs7dp7clnvl7', 'turning-raw-podcast-audio-into-a-season-trailer', 'Turning raw podcast audio into a season trailer', 'Lumen Podcast Co.', 'Media', 'A narrative podcast wanted a cinematic trailer to launch season two.', 'Video production was slow and inconsistent, with feedback scattered across email and chat.', 'A repeatable pipeline: brief → draft → feedback → approval, with predictable turnaround.', 'A dedicated editor, a structured brief and timestamped review on every draft.', 'Clean, cinematic, on-brand motion with tasteful sound design.', NULL, NULL, '/assets/demo/work-2.jpg', '{\"Turnaround\":\"3 days\",\"Videos / month\":\"12\",\"Revision rounds\":\"1.4 avg\"}', 'The process is what makes it — I always know where my project is.', 'Lumen Podcast Co.', '[\"Master edit\",\"Social cut-downs\",\"Captions\"]', '3 weeks', NULL, NULL, 'PUBLISHED', '1', '2026-09-30 20:14:14.436', '2026-09-30 20:14:14.436'),
('cmuojn06e01jvzs7dmr0ojp3t', 'cmuojlaux0000uz7de9mahyza', 'cmuojn05p01jlzs7do7k9enqa', 'a-launch-explainer-that-lifted-trial-sign-ups', 'A launch explainer that lifted trial sign-ups', 'Arcadia Software', 'SaaS', 'Arcadia needed a crisp 60-second explainer for their v3 launch.', 'Video production was slow and inconsistent, with feedback scattered across email and chat.', 'A repeatable pipeline: brief → draft → feedback → approval, with predictable turnaround.', 'A dedicated editor, a structured brief and timestamped review on every draft.', 'Clean, cinematic, on-brand motion with tasteful sound design.', NULL, NULL, '/assets/demo/work-3.jpg', '{\"Turnaround\":\"3 days\",\"Videos / month\":\"12\",\"Revision rounds\":\"1.4 avg\"}', 'The process is what makes it — I always know where my project is.', 'Arcadia Software', '[\"Master edit\",\"Social cut-downs\",\"Captions\"]', '3 weeks', NULL, NULL, 'PUBLISHED', '1', '2026-09-30 20:14:14.438', '2026-09-30 20:14:14.438');
