INSERT INTO `contract_versions` (`id`, `contractId`, `version`, `sections`, `variables`, `contentHash`, `createdById`, `createdAt`) VALUES
('cmuojmv3n0021zs7dk1jzorx4', 'cmuojmv3m0020zs7dyyfgdxqz', '1', '[{\"key\":\"parties\",\"body\":\"This agreement is between FaizanEdits Pro (the “Studio”) and Jordan Ellis of Northwind Realty Group (the “Client”), effective on the date the Client signs below.\",\"title\":\"1. Parties\"},{\"key\":\"scope\",\"body\":\"The Studio will provide video editing services for the project “Lakeside Estate — Launch Film” as described here:\\nCinematic 60-second launch film for a lakeside listing, cut for YouTube and Instagram.\",\"title\":\"2. Project scope\"},{\"key\":\"deliverables\",\"body\":\"The Studio will deliver:\\n• 1 × Horizontal tour\\n• 1 × Vertical social reel\\n• 1 × MLS-compliant version\\n• 1 × Agent branding\\n• 1 × Music-licensed exports\",\"title\":\"3. Deliverables\"},{\"key\":\"turnaround\",\"body\":\"The first draft will be delivered within 3 business days of the Studio receiving all required assets and the completed project brief. Delays in receiving assets or feedback extend the timeline accordingly.\",\"title\":\"4. Turnaround\"},{\"key\":\"payment\",\"body\":\"Total fee: $2,070.00. A deposit of $1,035.00 is due on signing; any remaining balance of $1,035.00 is due before final files are released, unless otherwise agreed in writing. Work begins once payment conditions for the deposit are met.\",\"title\":\"5. Payment terms\"},{\"key\":\"revisions\",\"body\":\"This agreement includes 2 round(s) of revisions. A round is one consolidated set of notes on a delivered draft. Additional rounds, or changes to the agreed scope after production has started, are handled as a change request and may be quoted separately.\",\"title\":\"6. Revisions\"},{\"key\":\"usage\",\"body\":\"On receipt of full payment the Studio grants the Client a perpetual, worldwide licence to use the final deliverables for the Client\'s business purposes. The Studio may display non-confidential excerpts in its portfolio unless the Client requests otherwise in writing.\",\"title\":\"7. Usage rights\"},{\"key\":\"confidentiality\",\"body\":\"Each party will keep the other\'s non-public materials confidential and use them only for this project. Client footage and assets are stored in access-controlled storage and only shared with team members working on the project.\",\"title\":\"8. Confidentiality\"},{\"key\":\"cancellation\",\"body\":\"Either party may cancel with written notice. Work completed to the date of cancellation is billable. Deposits cover time reserved and work performed.\",\"title\":\"9. Cancellation\"},{\"key\":\"refunds\",\"body\":\"Because the Studio reserves time and begins work on payment, deposits are non-refundable once production has started. If the Studio cannot deliver the agreed scope, the Client will receive a refund for the undelivered portion.\",\"title\":\"10. Refunds\"},{\"key\":\"ownership\",\"body\":\"The Client retains ownership of all supplied footage, brand assets and materials. The Studio retains ownership of its working files, templates and methods, except where source files are listed as deliverables.\",\"title\":\"11. Ownership\"},{\"key\":\"approval\",\"body\":\"Approval of a version in the Studio\'s review portal confirms the deliverable meets the agreed requirements. After approval, further changes are treated as a new request.\",\"title\":\"12. Approval\"}]', '{\"scope\":\"Cinematic 60-second launch film for a lakeside listing, cut for YouTube and Instagram.\",\"total\":\"$2,070.00\",\"balance\":\"$1,035.00\",\"company\":\"Northwind Realty Group\",\"deposit\":\"$1,035.00\",\"turnaround\":\"3 business days\",\"client_name\":\"Jordan Ellis\",\"studio_name\":\"FaizanEdits Pro\",\"deliverables\":\"• 1 × Horizontal tour\\n• 1 × Vertical social reel\\n• 1 × MLS-compliant version\\n• 1 × Agent branding\\n• 1 × Music-licensed exports\",\"project_name\":\"Lakeside Estate — Launch Film\",\"revision_rounds\":\"2\"}', 'e32449b796964f9be61f0f02af154adf70f75c5b67080eae4cc121161383db85', NULL, '2026-09-30 20:14:07.858'),
