('cmuojmyre011nzs7dpde8ox8g', 'cmuojmyrd011mzs7dt6y5lokj', '1', '[{\"key\":\"parties\",\"body\":\"This agreement is between FaizanEdits Pro (the “Studio”) and Devon Park of Arcadia Software (the “Client”), effective on the date the Client signs below.\",\"title\":\"1. Parties\"},{\"key\":\"scope\",\"body\":\"The Studio will provide video editing services for the project “Product Launch Explainer” as described here:\\n60-second animated explainer for the v3 launch.\",\"title\":\"2. Project scope\"},{\"key\":\"deliverables\",\"body\":\"The Studio will deliver:\\n• 1 × Product demo\\n• 1 × Explainer\\n• 1 × Feature announcement\\n• 1 × Onboarding tutorial\\n• 1 × Social cutdowns\",\"title\":\"3. Deliverables\"},{\"key\":\"turnaround\",\"body\":\"The first draft will be delivered within 5 business days of the Studio receiving all required assets and the completed project brief. Delays in receiving assets or feedback extend the timeline accordingly.\",\"title\":\"4. Turnaround\"},{\"key\":\"payment\",\"body\":\"Total fee: $2,990.00. A deposit of $1,495.00 is due on signing; any remaining balance of $1,495.00 is due before final files are released, unless otherwise agreed in writing. Work begins once payment conditions for the deposit are met.\",\"title\":\"5. Payment terms\"},{\"key\":\"revisions\",\"body\":\"This agreement includes 2 round(s) of revisions. A round is one consolidated set of notes on a delivered draft. Additional rounds, or changes to the agreed scope after production has started, are handled as a change request and may be quoted separately.\",\"title\":\"6. Revisions\"},{\"key\":\"usage\",\"body\":\"On receipt of full payment the Studio grants the Client a perpetual, worldwide licence to use the final deliverables for the Client\'s business purposes. The Studio may display non-confidential excerpts in its portfolio unless the Client requests otherwise in writing.\",\"title\":\"7. Usage rights\"},{\"key\":\"confidentiality\",\"body\":\"Each party will keep the other\'s non-public materials confidential and use them only for this project. Client footage and assets are stored in access-controlled storage and only shared with team members working on the project.\",\"title\":\"8. Confidentiality\"},{\"key\":\"cancellation\",\"body\":\"Either party may cancel with written notice. Work completed to the date of cancellation is billable. Deposits cover time reserved and work performed.\",\"title\":\"9. Cancellation\"},{\"key\":\"refunds\",\"body\":\"Because the Studio reserves time and begins work on payment, deposits are non-refundable once production has started. If the Studio cannot deliver the agreed scope, the Client will receive a refund for the undelivered portion.\",\"title\":\"10. Refunds\"},{\"key\":\"ownership\",\"body\":\"The Client retains ownership of all supplied footage, brand assets and materials. The Studio retains ownership of its working files, templates and methods, except where source files are listed as deliverables.\",\"title\":\"11. Ownership\"},{\"key\":\"approval\",\"body\":\"Approval of a version in the Studio\'s review portal confirms the deliverable meets the agreed requirements. After approval, further changes are treated as a new request.\",\"title\":\"12. Approval\"}]', '{\"scope\":\"60-second animated explainer for the v3 launch.\",\"total\":\"$2,990.00\",\"balance\":\"$1,495.00\",\"company\":\"Arcadia Software\",\"deposit\":\"$1,495.00\",\"turnaround\":\"5 business days\",\"client_name\":\"Devon Park\",\"studio_name\":\"FaizanEdits Pro\",\"deliverables\":\"• 1 × Product demo\\n• 1 × Explainer\\n• 1 × Feature announcement\\n• 1 × Onboarding tutorial\\n• 1 × Social cutdowns\",\"project_name\":\"Product Launch Explainer\",\"revision_rounds\":\"2\"}', '7f77232ec243d881037b7c59c05f824ee43c9a3130382a9864cd9802ecdc7ac9', NULL, '2026-09-30 20:14:12.601'),
('cmuojmz3u016kzs7degtxek6u', 'cmuojmz3t016jzs7dj7139s0r', '1', '[{\"key\":\"parties\",\"body\":\"This agreement is between FaizanEdits Pro (the “Studio”) and Lena Novak of Pixel Forge Studios (the “Client”), effective on the date the Client signs below.\",\"title\":\"1. Parties\"},{\"key\":\"scope\",\"body\":\"The Studio will provide video editing services for the project “Weekly Highlights — Sep wk 4” as described here:\\nWeekly gaming highlight reel for the main channel.\",\"title\":\"2. Project scope\"},{\"key\":\"deliverables\",\"body\":\"The Studio will deliver:\\n• 1 × Highlight videos\\n• 1 × Vertical clips\\n• 1 × Facecam layouts\\n• 1 × Thumbnails (optional)\",\"title\":\"3. Deliverables\"},{\"key\":\"turnaround\",\"body\":\"The first draft will be delivered within 5 business days of the Studio receiving all required assets and the completed project brief. Delays in receiving assets or feedback extend the timeline accordingly.\",\"title\":\"4. Turnaround\"},{\"key\":\"payment\",\"body\":\"Total fee: $736.00. A deposit of $368.00 is due on signing; any remaining balance of $368.00 is due before final files are released, unless otherwise agreed in writing. Work begins once payment conditions for the deposit are met.\",\"title\":\"5. Payment terms\"},{\"key\":\"revisions\",\"body\":\"This agreement includes 2 round(s) of revisions. A round is one consolidated set of notes on a delivered draft. Additional rounds, or changes to the agreed scope after production has started, are handled as a change request and may be quoted separately.\",\"title\":\"6. Revisions\"},{\"key\":\"usage\",\"body\":\"On receipt of full payment the Studio grants the Client a perpetual, worldwide licence to use the final deliverables for the Client\'s business purposes. The Studio may display non-confidential excerpts in its portfolio unless the Client requests otherwise in writing.\",\"title\":\"7. Usage rights\"},{\"key\":\"confidentiality\",\"body\":\"Each party will keep the other\'s non-public materials confidential and use them only for this project. Client footage and assets are stored in access-controlled storage and only shared with team members working on the project.\",\"title\":\"8. Confidentiality\"},{\"key\":\"cancellation\",\"body\":\"Either party may cancel with written notice. Work completed to the date of cancellation is billable. Deposits cover time reserved and work performed.\",\"title\":\"9. Cancellation\"},{\"key\":\"refunds\",\"body\":\"Because the Studio reserves time and begins work on payment, deposits are non-refundable once production has started. If the Studio cannot deliver the agreed scope, the Client will receive a refund for the undelivered portion.\",\"title\":\"10. Refunds\"},{\"key\":\"ownership\",\"body\":\"The Client retains ownership of all supplied footage, brand assets and materials. The Studio retains ownership of its working files, templates and methods, except where source files are listed as deliverables.\",\"title\":\"11. Ownership\"},{\"key\":\"approval\",\"body\":\"Approval of a version in the Studio\'s review portal confirms the deliverable meets the agreed requirements. After approval, further changes are treated as a new request.\",\"title\":\"12. Approval\"}]', '{\"scope\":\"Weekly gaming highlight reel for the main channel.\",\"total\":\"$736.00\",\"balance\":\"$368.00\",\"company\":\"Pixel Forge Studios\",\"deposit\":\"$368.00\",\"turnaround\":\"5 business days\",\"client_name\":\"Lena Novak\",\"studio_name\":\"FaizanEdits Pro\",\"deliverables\":\"• 1 × Highlight videos\\n• 1 × Vertical clips\\n• 1 × Facecam layouts\\n• 1 × Thumbnails (optional)\",\"project_name\":\"Weekly Highlights — Sep wk 4\",\"revision_rounds\":\"2\"}', '0fed1bfddbc58cf6aa9107c3a8beab3a1f79ebbc6370e3ea5bb1b0859164ff84', NULL, '2026-09-30 20:14:13.049'),
('cmuojmzqg01e6zs7dz1q8n9qf', 'cmuojmzqf01e5zs7dz6yc6vm9', '1', '[{\"key\":\"parties\",\"body\":\"This agreement is between FaizanEdits Pro (the “Studio”) and Lena Novak of Pixel Forge Studios (the “Client”), effective on the date the Client signs below.\",\"title\":\"1. Parties\"},{\"key\":\"scope\",\"body\":\"The Studio will provide video editing services for the project “Channel Trailer Refresh” as described here:\\nNew 45-second channel trailer.\",\"title\":\"2. Project scope\"},{\"key\":\"deliverables\",\"body\":\"The Studio will deliver:\\n• 1 × Master 16:9 edit up to 4K\\n• 1 × Chapters & timestamps\\n• 1 × Captions / SRT file\\n• 1 × Optional thumbnail\\n• 1 × Optional Shorts cutdowns\",\"title\":\"3. Deliverables\"},{\"key\":\"turnaround\",\"body\":\"The first draft will be delivered within 5 business days of the Studio receiving all required assets and the completed project brief. Delays in receiving assets or feedback extend the timeline accordingly.\",\"title\":\"4. Turnaround\"},{\"key\":\"payment\",\"body\":\"Total fee: $828.00. A deposit of $414.00 is due on signing; any remaining balance of $414.00 is due before final files are released, unless otherwise agreed in writing. Work begins once payment conditions for the deposit are met.\",\"title\":\"5. Payment terms\"},{\"key\":\"revisions\",\"body\":\"This agreement includes 2 round(s) of revisions. A round is one consolidated set of notes on a delivered draft. Additional rounds, or changes to the agreed scope after production has started, are handled as a change request and may be quoted separately.\",\"title\":\"6. Revisions\"},{\"key\":\"usage\",\"body\":\"On receipt of full payment the Studio grants the Client a perpetual, worldwide licence to use the final deliverables for the Client\'s business purposes. The Studio may display non-confidential excerpts in its portfolio unless the Client requests otherwise in writing.\",\"title\":\"7. Usage rights\"},{\"key\":\"confidentiality\",\"body\":\"Each party will keep the other\'s non-public materials confidential and use them only for this project. Client footage and assets are stored in access-controlled storage and only shared with team members working on the project.\",\"title\":\"8. Confidentiality\"},{\"key\":\"cancellation\",\"body\":\"Either party may cancel with written notice. Work completed to the date of cancellation is billable. Deposits cover time reserved and work performed.\",\"title\":\"9. Cancellation\"},{\"key\":\"refunds\",\"body\":\"Because the Studio reserves time and begins work on payment, deposits are non-refundable once production has started. If the Studio cannot deliver the agreed scope, the Client will receive a refund for the undelivered portion.\",\"title\":\"10. Refunds\"},{\"key\":\"ownership\",\"body\":\"The Client retains ownership of all supplied footage, brand assets and materials. The Studio retains ownership of its working files, templates and methods, except where source files are listed as deliverables.\",\"title\":\"11. Ownership\"},{\"key\":\"approval\",\"body\":\"Approval of a version in the Studio\'s review portal confirms the deliverable meets the agreed requirements. After approval, further changes are treated as a new request.\",\"title\":\"12. Approval\"}]', '{\"scope\":\"New 45-second channel trailer.\",\"total\":\"$828.00\",\"balance\":\"$414.00\",\"company\":\"Pixel Forge Studios\",\"deposit\":\"$414.00\",\"turnaround\":\"5 business days\",\"client_name\":\"Lena Novak\",\"studio_name\":\"FaizanEdits Pro\",\"deliverables\":\"• 1 × Master 16:9 edit up to 4K\\n• 1 × Chapters & timestamps\\n• 1 × Captions / SRT file\\n• 1 × Optional thumbnail\\n• 1 × Optional Shorts cutdowns\",\"project_name\":\"Channel Trailer Refresh\",\"revision_rounds\":\"2\"}', '0da6c32cf01c69517af2599540c70abf0f1780f26353f24069468cbed68a2701', NULL, '2026-09-30 20:14:13.863');
