('cmuojmzz001h8zs7do5glb5y7', 'cmuojlaux0000uz7de9mahyza', 'cmuojmuud000dzs7dyp6obajb', 'cmuojmuuk000ezs7dz6ufopz3', 'cmuojmwfa009uzs7dowphv7mm', 'cmuojmusf0004zs7dgowyupvw', 'PROJECT_MANAGER', 'Hi team — quick question: can the agent\'s headshot stay on screen a bit longer in the closing card?', '[]', '[]', '1', '2026-09-30 20:14:14.172'),
('cmuojmzzk01hczs7d8q1pob8b', 'cmuojlaux0000uz7de9mahyza', 'cmuojmuud000dzs7dyp6obajb', 'cmuojmuuk000ezs7dz6ufopz3', 'cmuojmwfa009uzs7dowphv7mm', 'cmuojmus10001zs7d9hb8bv3i', 'CLIENT', 'Absolutely, Jordan. Marco will extend it to 4 seconds in the next revision. Anything else you\'d like changed while we\'re in there?', '[]', '[]', '1', '2026-09-30 20:14:14.192'),
('cmuojn00501hkzs7d6f01m42s', 'cmuojlaux0000uz7de9mahyza', 'cmuojmuud000dzs7dyp6obajb', 'cmuojmuuk000ezs7dz6ufopz3', 'cmuojmwfa009uzs7dowphv7mm', 'cmuojmusf0004zs7dgowyupvw', 'PROJECT_MANAGER', 'That\'s it for now — thank you! The drone opener looks fantastic.', '[]', '[]', '1', '2026-09-30 20:14:14.213'),
('cmuojn00r01hyzs7drsjljjfl', 'cmuojlaux0000uz7de9mahyza', 'cmuojmuv2000izs7d407wiikd', 'cmuojmuv6000jzs7dpxvv1ryz', 'cmuojmy8800uhzs7ddl972j52', 'cmuojmusj0005zs7dahwxl3qt', 'PROJECT_MANAGER', 'Notes are in the player. The second guest\'s audio dips around the 10 second mark — is that something you can fix?', '[]', '[]', '1', '2026-09-30 20:14:14.235'),
('cmuojn01501i0zs7d9m5rw07m', 'cmuojlaux0000uz7de9mahyza', 'cmuojmuv2000izs7d407wiikd', 'cmuojmuv6000jzs7dpxvv1ryz', 'cmuojmy8800uhzs7ddl972j52', 'cmuojmus50002zs7d1c8c4oyr', 'CLIENT', 'Yes — I\'ll re-balance both mics and add a gentle de-esser. V2 will be with you tomorrow.', '[]', '[]', '1', '2026-09-30 20:14:14.249');
