('cmuojmzzd01hbzs7dxt8l8ckn', 'cmuojlaux0000uz7de9mahyza', 'cmuojmus10001zs7d9hb8bv3i', 'MESSAGE', 'message.received', 'Jordan Ellis sent a message on Harbor View Estate — Listing Tour', 'Hi team — quick question: can the agent\'s headshot stay on screen a bit longer in the closing card?', '/admin/projects/cmuojmwfa009uzs7dowphv7mm?tab=messages', NULL, '1', '2026-09-30 20:14:14.185'),
('cmuojmzzx01hgzs7dj9vgcf6m', 'cmuojlaux0000uz7de9mahyza', 'cmuojmusf0004zs7dgowyupvw', 'MESSAGE', 'message.reply', 'New message from Sam Rivera', 'Absolutely, Jordan. Marco will extend it to 4 seconds in the next revision. Anything else you\'d like changed while we\'re in there?', '/dashboard/projects/cmuojmwfa009uzs7dowphv7mm?tab=messages', NULL, '1', '2026-09-30 20:14:14.205'),
