('cmuojn01c01i1zs7d3bixwtk4', 'cmuojlaux0000uz7de9mahyza', 'cmuojmusj0005zs7dahwxl3qt', 'MESSAGE', 'message.reply', 'New message from Marco Silva', 'Yes — I\'ll re-balance both mics and add a gentle de-esser. V2 will be with you tomorrow.', '/dashboard/projects/cmuojmy8800uhzs7ddl972j52?tab=messages', NULL, '1', '2026-09-30 20:14:14.256'),
