INSERT INTO `testimonials` (`id`, `workspaceId`, `projectId`, `clientId`, `rating`, `quote`, `permissionToPublish`, `name`, `role`, `company`, `imageUrl`, `status`, `featured`, `isDemo`, `createdAt`, `updatedAt`) VALUES
('cmuojmwdu009kzs7d7meoaw2g', 'cmuojlaux0000uz7de9mahyza', 'cmuojmuxe0013zs7d7opuoqj7', 'cmuojmuuk000ezs7dz6ufopz3', '5', 'The launch film brought three offers in the first week. Fast, polished and genuinely easy to work with — the review player made feedback painless.', '1', 'Jordan Ellis', NULL, 'Northwind Realty Group', NULL, 'APPROVED', '1', '1', '2026-09-30 20:14:09.522', '2026-09-30 20:14:14.439'),
('cmuojmy7700u7zs7dlxqhjz1a', 'cmuojlaux0000uz7de9mahyza', 'cmuojmxiz00ljzs7dmwgx7pgt', 'cmuojmuv6000jzs7dpxvv1ryz', '5', 'They turned ninety minutes of raw audio into a trailer we are proud of. Communication was excellent from start to finish.', '1', 'Mia Chen', NULL, 'Lumen Podcast Co.', NULL, 'APPROVED', '1', '1', '2026-09-30 20:14:11.875', '2026-09-30 20:14:14.439'),
('cmuojn06i01jwzs7don383bx1', 'cmuojlaux0000uz7de9mahyza', NULL, NULL, '5', 'Clear communication, sharp edits and zero back-and-forth chaos. It feels like an in-house team.', '1', 'Devon Park', 'Head of Marketing', 'Arcadia Software', NULL, 'APPROVED', '1', '1', '2026-09-30 20:14:14.442', '2026-09-30 20:14:14.442'),
('cmuojn06j01jxzs7dps4e8tnv', 'cmuojlaux0000uz7de9mahyza', NULL, NULL, '5', 'My weekly uploads went from a scramble to a system. The review tool alone is worth it.', '1', 'Lena Novak', 'Creator', 'Pixel Forge Studios', NULL, 'APPROVED', '1', '1', '2026-09-30 20:14:14.443', '2026-09-30 20:14:14.443');
